1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Step =
14	  | { op: "quote"; items: Item[] }
15	  | { op: "claim"; policy: number; incident: { cause: string; damages: Damage[] } };
16	
17	export type Customer = { yearsWithMHPCO: number };
18	
19	export type Scenario = {
20	  customer: Customer;
21	  steps: Step[];
22	};
23	
24	export type StepResult = { premium: number } | { payout: number; remainingCap: number };
25	
26	const PROCESSING_FEE = 5;
27	const FIRST_INSURANCE_SURCHARGE_PERCENT = 10;
28	
29	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
30	  sword: 100,
31	  amulet: 60,
32	  staff: 80,
33	  potion: 40,
34	  rune: 25,
35	  moonstone: 25,
36	};
37	
38	// Item types are looked up in several tables; an unknown type is always an error
39	// rather than a silent 0, whichever table asked.
40	const lookUpByItemType = (
41	  table: Record<string, number>,
42	  itemType: string,
43	): number => {
44	  const value = table[itemType];
45	  if (value === undefined) {
46	    throw new Error(`Unknown item type: ${itemType}`);
47	  }
48	  return value;
49	};
50	
51	const basePremiumPerItemOf = (itemType: string): number =>
52	  lookUpByItemType(BASE_PREMIUM_BY_ITEM_TYPE, itemType);
53	
54	// Percentages are always taken as `amount * percent / 100`, never `amount * 1.15`:
55	// exact fractional intermediates, a single rounding at the very end.
56	const percentOf = (amount: number, percent: number): number =>
57	  (amount * percent) / 100;
58	
59	const COMPONENT_BLOCK_SIZE = 3;
60	const COMPONENT_BLOCK_BASE_PREMIUM = 60;
61	
62	const countByItemType = (items: Item[]): Map<string, number> =>
63	  items.reduce(
64	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
65	    new Map<string, number>(),
66	  );
67	
68	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
69	
70	const isComponent = (itemType: string): boolean =>
71	  COMPONENT_TYPES.has(itemType);
72	
73	const basePremiumForCountOf = (itemType: string, count: number): number =>
74	  isComponent(itemType) && count === COMPONENT_BLOCK_SIZE
75	    ? COMPONENT_BLOCK_BASE_PREMIUM
76	    : count * basePremiumPerItemOf(itemType);
77	
78	const sum = (amounts: number[]): number =>
79	  amounts.reduce((total, amount) => total + amount, 0);
80	
81	const policyBasePremiumOf = (items: Item[]): number =>
82	  sum(
83	    [...countByItemType(items)].map(([itemType, count]) =>
84	      basePremiumForCountOf(itemType, count),
85	    ),
86	  );
87	
88	const CURSE_SURCHARGE_PERCENT = 50;
89	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
90	const HIGH_ENCHANTMENT_LEVEL = 5;
91	
92	const isHighlyEnchanted = (item: Item): boolean =>
93	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
94	
95	const itemSurchargePercentOf = (item: Item): number =>
96	  (item.cursed ? CURSE_SURCHARGE_PERCENT : 0) +
97	  (isHighlyEnchanted(item) ? HIGH_ENCHANTMENT_SURCHARGE_PERCENT : 0);
98	
99	// Item-level modifiers apply to the affected ITEM's own base premium.
100	const itemSurchargesOf = (items: Item[]): number =>
101	  sum(
102	    items.map((item) =>
103	      percentOf(basePremiumPerItemOf(item.type), itemSurchargePercentOf(item)),
104	    ),
105	  );
106	
107	const LOYALTY_DISCOUNT_PERCENT = 20;
108	const LOYALTY_YEARS = 2;
109	const FOLLOW_UP_DISCOUNT_PERCENT = 15;
110	
111	const isLongStanding = (customer: Customer): boolean =>
112	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
113	
114	// Policy-wide modifiers are signed percentages OF THE POLICY BASE PREMIUM (the sum
115	// of item base premiums) — never of the running total, so item surcharges stay
116	// outside their scope. Positive is a surcharge, negative a discount. Adding a
117	// policy-wide modifier means adding one entry here.
118	const policyModifierPercentsOf = (
119	  customer: Customer,
120	  isFollowUpContract: boolean,
121	): number[] => [
122	  FIRST_INSURANCE_SURCHARGE_PERCENT,
123	  ...(isLongStanding(customer) ? [-LOYALTY_DISCOUNT_PERCENT] : []),
124	  ...(isFollowUpContract ? [-FOLLOW_UP_DISCOUNT_PERCENT] : []),
125	];
126	
127	const quotePremium = (
128	  items: Item[],
129	  customer: Customer,
130	  isFollowUpContract: boolean,
131	): number => {
132	  const policyBasePremium = policyBasePremiumOf(items);
133	  const policyModifiers = sum(
134	    policyModifierPercentsOf(customer, isFollowUpContract).map((percent) =>
135	      percentOf(policyBasePremium, percent),
136	    ),
137	  );
138	
139	  // The processing fee is added last, after every modifier.
140	  return Math.ceil(
141	    policyBasePremium +
142	      itemSurchargesOf(items) +
143	      policyModifiers +
144	      PROCESSING_FEE,
145	  );
146	};
147	
148	const INSURANCE_VALUE_BY_ITEM_TYPE: Record<string, number> = {
149	  sword: 1000,
150	  amulet: 600,
151	  staff: 800,
152	  potion: 400,
153	  rune: 250,
154	  moonstone: 250,
155	};
156	
157	const DEDUCTIBLE_PER_DAMAGE = 100;
158	const CAP_MULTIPLIER = 2;
159	
160	const insuranceValuePerItemOf = (itemType: string): number =>
161	  lookUpByItemType(INSURANCE_VALUE_BY_ITEM_TYPE, itemType);
162	
163	const insuranceSumOf = (items: Item[]): number =>
164	  sum(items.map((item) => insuranceValuePerItemOf(item.type)));
165	
166	// The claim-side enchantment threshold (8) is deliberately distinct from the
167	// premium-side one (HIGH_ENCHANTMENT_LEVEL, 5) — different rules, different numbers.
168	const REDUCED_REIMBURSEMENT_LEVEL = 8;
169	const REDUCED_REIMBURSEMENT_PERCENT = 50;
170	
171	const isReducedReimbursement = (item: Item): boolean =>
172	  (item.enchantment ?? 0) >= REDUCED_REIMBURSEMENT_LEVEL;
173	
174	// How much of the damage the policy covers, BEFORE the deductible. Heavily
175	// enchanted items are reimbursed at half; everything else in full. (The spec's
176	// "dragon material is fully reimbursed" clause is not expressed separately: full
177	// reimbursement is already the default here, and every dragon example agrees.)
178	const coveredAmountOf = (damage: Damage, item: Item): number =>
179	  isReducedReimbursement(item)
180	    ? percentOf(damage.amount, REDUCED_REIMBURSEMENT_PERCENT)
181	    : damage.amount;
182	
183	const payoutForDamage = (damage: Damage, item: Item): number =>
184	  coveredAmountOf(damage, item) - DEDUCTIBLE_PER_DAMAGE;
185	
186	// A policy is what a quote step leaves behind for later claim steps to draw on:
187	// the insured items and the cap those items entitle the holder to. `remainingCap`
188	// is the only thing a claim consumes, so it is the one mutable field.
189	type Policy = {
190	  insuredItems: Item[];
191	  remainingCap: number;
192	};
193	
194	const issuePolicy = (insuredItems: Item[]): Policy => ({
195	  insuredItems,
196	  remainingCap: CAP_MULTIPLIER * insuranceSumOf(insuredItems),
197	});
198	
199	// Each damage entry is a separate damaged item, so entries consume the insured
200	// items one for one: two sword damages need two insured swords.
201	const damagedItemsOf = (policy: Policy, damages: Damage[]): Item[] => {
202	  const unclaimedItems = [...policy.insuredItems];
203	
204	  return damages.map((damage) => {
205	    if (damage.amount < 0) {
206	      throw new Error(
207	        `Damage amount must not be negative: ${damage.amount} for ${damage.itemType}`,
208	      );
209	    }
210	
211	    const index = unclaimedItems.findIndex(
212	      (item) => item.type === damage.itemType,
213	    );
214	    if (index === -1) {
215	      throw new Error(
216	        `Damage entry not covered by the policy: ${damage.itemType}`,
217	      );
218	    }
219	
220	    return unclaimedItems.splice(index, 1)[0];
221	  });
222	};
223	
224	const settleClaim = (policy: Policy, damages: Damage[]): StepResult => {
225	  const damagedItems = damagedItemsOf(policy, damages);
226	  const desiredPayout = Math.floor(
227	    sum(
228	      damages.map((damage, index) =>
229	        payoutForDamage(damage, damagedItems[index]),
230	      ),
231	    ),
232	  );
233	
234	  // The cap is a per-policy budget: what a claim pays out, it consumes.
235	  const payout = Math.min(desiredPayout, policy.remainingCap);
236	  policy.remainingCap -= payout;
237	
238	  return { payout, remainingCap: policy.remainingCap };
239	};
240	
241	export const runScenario = (scenario: Scenario): StepResult[] => {
242	  // A claim's `policy` is the index of the QUOTE STEP that issued it, so policies
243	  // are keyed by step index rather than by order of issue — the two differ as soon
244	  // as quotes and claims interleave.
245	  const policiesByStep = new Map<number, Policy>();
246	
247	  const hasExistingPolicy = (): boolean => policiesByStep.size > 0;
248	
249	  return scenario.steps.map((step, stepIndex) => {
250	    if (step.op === "claim") {
251	      const policy = policiesByStep.get(step.policy);
252	      if (policy === undefined) {
253	        throw new Error(`Claim references no policy at step ${step.policy}`);
254	      }
255	      return settleClaim(policy, step.incident.damages);
256	    }
257	
258	    const premium = quotePremium(
259	      step.items,
260	      scenario.customer,
261	      hasExistingPolicy(),
262	    );
263	    policiesByStep.set(stepIndex, issuePolicy(step.items));
264	
265	    return { premium };
266	  });
267	};
